}));

describe("resolveToolWithOverride", () => {
  beforeEach(() => {
    invokeMock.mockReset();
  });

  it("empty overrides return the probed result untouched", async () => {
    const probed = { status: "found" as const, path: "C:\\auto\\ms.exe" };
